from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/kinetic';html=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page(viewport={'width':1440,'height':1100});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready');p.locator('.kinetic-launch button').click();p.locator('#fight-practice').click();p.wait_for_function("SVG_FIGHTER.state.screen==='battle'")
 rows=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,K=INK.Kinetic,rows=[],check=(name,passed)=>rows.push({name,passed});G.paused=true;A.reset();G.paused=true;A.teleport(0,560);A.teleport(1,765);document.getElementById('autohp').checked=false;A.inputMove(0,'sHP');A.step(5);const f=A.fighters[0],base=A.pose(f),on=INK.Runtime.visual(f,base);K.settings.enabled=false;const off=INK.Runtime.visual(f,base);K.settings.enabled=true;check('Startup produces shoulder and weight-transfer motion',JSON.stringify(on)!==JSON.stringify(off));
 for(let i=0;i<40&&!K.inspect().events.length;i++)A.step();const events=K.inspect().events;check('Real heavy contact drives the shared response event',events.some(e=>e.type==='hit'));check('Victim receives compression and attacker receives recoil',!!A.fighters[1]._inkReaction&&!!f._inkRecoil);const light=A.getMove(f,'sLP'),heavy=A.getMove(f,'sHP'),tempo=INK.CombatFlow;check('New hit rhythm distinguishes light, heavy and punish',tempo.contact(G,light,'hit',true)===3&&tempo.contact(G,heavy,'hit',true)===9&&tempo.contact(G,heavy,'hit',true,{punish:true})===11);K.settings.enabled=false;check('Legacy comparison restores original heavy hitstop',tempo.contact(G,heavy,'hit',true)===7);K.settings.enabled=true;const hp=A.fighters[1].hp;A.render();INK.VFX.render(G,1);const count=K.inspect().events.length;for(let i=0;i<15;i++){A.renderFraction(.4);INK.VFX.render(G,.4);}check('Rendering cannot repeat contacts or change damage',K.inspect().events.length===count&&A.fighters[1].hp===hp);check('Impact composition stays within twelve retained slots',K.inspect().slots===12);return rows;}''')
 p.locator('#f-battle-mount').screenshot(path=str(O/'heavy-contact.png'))
 p.evaluate("SVG_FIGHTER.reset();SVG_FIGHTER.state.paused=true;SVG_FIGHTER.teleport(0,560);SVG_FIGHTER.teleport(1,765);document.getElementById('dummy').value='guard';SVG_FIGHTER.inputMove(0,'sHP');SVG_FIGHTER.step(30)")
 rows.append({'name':'Guard contact uses its own feedback category','passed':p.evaluate("INK.Kinetic.inspect().events.some(e=>e.type==='block')")})
 rows.append({'name':'Eight characters remain playable with finite motion and contact effects','passed':p.evaluate('''()=>{const A=SVG_FIGHTER;for(const id of INK.Schema.CHARACTERS){A.start(id,'ryu','demo','classic',28);A.state.paused=true;for(let i=0;i<300;i++){A.step();if(i%30===0){A.render();INK.VFX.render(A.state,1);for(const f of A.fighters){const p=A.visualPose(f);if(![f.x,f.y,f.hp,p.lean,p.bob,...p.fw,...p.fa].every(Number.isFinite))return false;}}}}return INK.Kinetic.inspect().events.length<=32;}''')})
 p.locator('#kinetic-character').select_option('mai');p.wait_for_function("SVG_FIGHTER.fighters[0].ch.id==='mai'");p.locator('#kinetic-jump').click();p.wait_for_function("SVG_FIGHTER.fighters[0].y<0");p.wait_for_function("INK.Kinetic.inspect().events.some(e=>e.type==='landing')");rows.append({'name':'Character selector and jump control produce a real landing response','passed':p.evaluate("SVG_FIGHTER.fighters[0].ch.id==='mai' && !!SVG_FIGHTER.fighters[0]._inkWeight")})
 p.evaluate("SVG_FIGHTER.state.paused=true;SVG_FIGHTER.render();INK.VFX.render(SVG_FIGHTER.state,1)")
 p.locator('#f-battle-mount').screenshot(path=str(O/'mai-landing.png'))
 p.set_viewport_size({'width':390,'height':844});p.locator('#kinetic-panel').screenshot(path=str(O/'mobile-panel.png'));rows.append({'name':'Control panel fits a narrow viewport','passed':p.evaluate("document.querySelector('#kinetic-panel').getBoundingClientRect().right<=innerWidth+1")})
 b.close()
